// Both exports hand back a boolean. The contract closes `returns` over one plain
// return for `isReady` only; `isReadyOpen` is the control, identical except
// that its `returns` is left open.
//
// The signatures are `tsc`-clean on purpose: reading the result in a
// conditional is well typed under these declarations, so nothing here
// duplicates a type diagnostic.
export declare function isReady(): boolean;
export declare function isReadyOpen(): boolean;
